const { Transform } = require('stream');
const up = new Transform({
  transform(chunk, enc, cb) { cb(null, chunk.toString().toUpperCase()); }
});
let out = '';
up.on('data', d => out += d);
up.on('end', () => {
  console.log('transformed=' + out);
  console.log('done=' + (out === 'HELLO NODE STREAM'));
});
up.write('hello ');
up.write('node ');
up.write('stream');
up.end();
